173	    @Override
174	    void apply(RequestBuilder builder, @Nullable Map<String, T> value) throws IOException {
175	      if (value == null) {
176	        throw Utils.parameterError(method, p, "Query map was null");
177	      }
178	
179	      for (Map.Entry<String, T> entry : value.entrySet()) {
180	        String entryKey = entry.getKey();
181	        if (entryKey == null) {
182	          throw Utils.parameterError(method, p, "Query map contained null key.");
183	        }
184	        T entryValue = entry.getValue();
185	        if (entryValue == null) {
186	          throw Utils.parameterError(
187	              method, p, "Query map contained null value for key '" + entryKey + "'.");
188	        }
189	
190	        String convertedEntryValue = valueConverter.convert(entryValue);
191	        if (convertedEntryValue == null) {
192	          throw Utils.parameterError(
193	              method,
194	              p,
195	              "Query map value '"
196	                  + entryValue
197	                  + "' converted to null by "
198	                  + valueConverter.getClass().getName()
199	                  + " for key '"
200	                  + entryKey
201	                  + "'.");
202	        }
203	
204	        builder.addQueryParam(entryKey, convertedEntryValue, encoded);
205	      }
206	    }
207	  }
