65	
66	final class RequestFactory {
67	  static RequestFactory parseAnnotations(Retrofit retrofit, Class<?> service, Method method) {
68	    return new Builder(retrofit, service, method).build();
69	  }
70	
71	  private final Class<?> service;
72	  private final Method method;
73	  private final HttpUrl baseUrl;
74	  final String httpMethod;
75	  private final @Nullable String relativeUrl;
76	  private final @Nullable Headers headers;
77	  private final @Nullable MediaType contentType;
78	  private final boolean hasBody;
79	  private final boolean isFormEncoded;
80	  private final boolean isMultipart;
81	  private final ParameterHandler<?>[] parameterHandlers;
82	  final boolean isKotlinSuspendFunction;
83	
84	  RequestFactory(Builder builder) {
85	    service = builder.service;
86	    method = builder.method;
87	    baseUrl = builder.retrofit.baseUrl;
88	    httpMethod = builder.httpMethod;
89	    relativeUrl = builder.relativeUrl;
90	    headers = builder.headers;
91	    contentType = builder.contentType;
92	    hasBody = builder.hasBody;
93	    isFormEncoded = builder.isFormEncoded;
94	    isMultipart = builder.isMultipart;
95	    parameterHandlers = builder.parameterHandlers;
96	    isKotlinSuspendFunction = builder.isKotlinSuspendFunction;
97	  }
98	
99	  okhttp3.Request create(@Nullable Object instance, Object[] args) throws IOException {
100	    @SuppressWarnings("unchecked") // It is an error to invoke a method with the wrong arg types.
101	    ParameterHandler<Object>[] handlers = (ParameterHandler<Object>[]) parameterHandlers;
102	
103	    int argumentCount = args.length;
104	    if (argumentCount != handlers.length) {
105	      throw new IllegalArgumentException(
106	          "Argument count ("
107	              + argumentCount
108	              + ") doesn't match expected count ("
109	              + handlers.length
110	              + ")");
111	    }
112	
113	    RequestBuilder requestBuilder =
114	        new RequestBuilder(
115	            httpMethod,
116	            baseUrl,
117	            relativeUrl,
118	            headers,
119	            contentType,
120	            hasBody,
121	            isFormEncoded,
122	            isMultipart);
123	
124	    if (isKotlinSuspendFunction) {
125	      // The Continuation is the last parameter and the handlers array contains null at that index.
126	      argumentCount--;
127	    }
128	
129	    List<Object> argumentList = new ArrayList<>(argumentCount);
130	    for (int p = 0; p < argumentCount; p++) {
131	      argumentList.add(args[p]);
132	      handlers[p].apply(requestBuilder, args[p]);
133	    }
134	
135	    return requestBuilder
136	        .get()
137	        .tag(Invocation.class, new Invocation(service, instance, method, argumentList, relativeUrl))
138	        .build();
139	  }
140	
141	  /**
142	   * Inspects the annotations on an interface method to construct a reusable service method. This
143	   * requires potentially-expensive reflection so it is best to build each service method only once
144	   * and reuse it. Builders cannot be reused.
145	   */
146	  static final class Builder {
147	    // Upper and lower characters, digits, underscores, and hyphens, starting with a character.
148	    private static final String PARAM = "[a-zA-Z][a-zA-Z0-9_-]*";
149	    private static final Pattern PARAM_URL_REGEX = Pattern.compile("\\{(" + PARAM + ")\\}");
150	    private static final Pattern PARAM_NAME_REGEX = Pattern.compile(PARAM);
151	
152	    final Retrofit retrofit;
153	    final Class<?> service;
154	    final Method method;
155	    final Annotation[] methodAnnotations;
156	    final Annotation[][] parameterAnnotationsArray;
157	    final Type[] parameterTypes;
158	
159	    boolean gotField;
160	    boolean gotPart;
161	    boolean gotBody;
162	    boolean gotPath;
163	    boolean gotQuery;
164	    boolean gotQueryName;
165	    boolean gotQueryMap;
166	    boolean gotUrl;
167	    @Nullable String httpMethod;
168	    boolean hasBody;
169	    boolean isFormEncoded;
170	    boolean isMultipart;
171	    @Nullable String relativeUrl;
172	    @Nullable Headers headers;
173	    @Nullable MediaType contentType;
174	    @Nullable Set<String> relativeUrlParamNames;
175	    @Nullable ParameterHandler<?>[] parameterHandlers;
176	    boolean isKotlinSuspendFunction;
