370	    @Nullable
371	    private ParameterHandler<?> parseParameterAnnotation(
372	        int p, Type type, Annotation[] annotations, Annotation annotation) {
373	      if (annotation instanceof Url) {
374	        validateResolvableType(p, type);
375	        if (gotUrl) {
376	          throw parameterError(method, p, "Multiple @Url method annotations found.");
377	        }
378	        if (gotPath) {
379	          throw parameterError(method, p, "@Path parameters may not be used with @Url.");
380	        }
381	        if (gotQuery) {
382	          throw parameterError(method, p, "A @Url parameter must not come after a @Query.");
383	        }
384	        if (gotQueryName) {
385	          throw parameterError(method, p, "A @Url parameter must not come after a @QueryName.");
386	        }
387	        if (gotQueryMap) {
388	          throw parameterError(method, p, "A @Url parameter must not come after a @QueryMap.");
389	        }
390	        if (relativeUrl != null) {
391	          throw parameterError(method, p, "@Url cannot be used with @%s URL", httpMethod);
392	        }
393	
394	        gotUrl = true;
395	
396	        if (type == HttpUrl.class
397	            || type == String.class
398	            || type == URI.class
399	            || (type instanceof Class && "android.net.Uri".equals(((Class<?>) type).getName()))) {
400	          return new ParameterHandler.RelativeUrl(method, p);
401	        } else {
402	          throw parameterError(
403	              method,
404	              p,
405	              "@Url must be okhttp3.HttpUrl, String, java.net.URI, or android.net.Uri type.");
406	        }
407	
408	      } else if (annotation instanceof Path) {
409	        validateResolvableType(p, type);
410	        if (gotQuery) {
411	          throw parameterError(method, p, "A @Path parameter must not come after a @Query.");
412	        }
413	        if (gotQueryName) {
414	          throw parameterError(method, p, "A @Path parameter must not come after a @QueryName.");
415	        }
416	        if (gotQueryMap) {
417	          throw parameterError(method, p, "A @Path parameter must not come after a @QueryMap.");
418	        }
419	        if (gotUrl) {
420	          throw parameterError(method, p, "@Path parameters may not be used with @Url.");
421	        }
422	        if (relativeUrl == null) {
423	          throw parameterError(
424	              method, p, "@Path can only be used with relative url on @%s", httpMethod);
425	        }
426	        gotPath = true;
427	
428	        Path path = (Path) annotation;
429	        String name = path.value();
430	        validatePathName(p, name);
431	
432	        Converter<?, String> converter = retrofit.stringConverter(type, annotations);
433	        return new ParameterHandler.Path<>(method, p, name, converter, path.encoded());
434	
435	      } else if (annotation instanceof Query) {
436	        validateResolvableType(p, type);
437	        Query query = (Query) annotation;
438	        String name = query.value();
439	        boolean encoded = query.encoded();
440	
441	        Class<?> rawParameterType = Utils.getRawType(type);
442	        gotQuery = true;
443	        if (Iterable.class.isAssignableFrom(rawParameterType)) {
444	          if (!(type instanceof ParameterizedType)) {
445	            throw parameterError(
446	                method,
447	                p,
448	                rawParameterType.getSimpleName()
449	                    + " must include generic type (e.g., "
450	                    + rawParameterType.getSimpleName()
451	                    + "<String>)");
452	          }
453	          ParameterizedType parameterizedType = (ParameterizedType) type;
454	          Type iterableType = Utils.getParameterUpperBound(0, parameterizedType);
455	          Converter<?, String> converter = retrofit.stringConverter(iterableType, annotations);
456	          return new ParameterHandler.Query<>(name, converter, encoded).iterable();
457	        } else if (rawParameterType.isArray()) {
458	          Class<?> arrayComponentType = boxIfPrimitive(rawParameterType.getComponentType());
459	          Converter<?, String> converter =
460	              retrofit.stringConverter(arrayComponentType, annotations);
461	          return new ParameterHandler.Query<>(name, converter, encoded).array();
462	        } else {
463	          Converter<?, String> converter = retrofit.stringConverter(type, annotations);
464	          return new ParameterHandler.Query<>(name, converter, encoded);
465	        }
466	
467	      } else if (annotation instanceof QueryName) {
468	        validateResolvableType(p, type);
469	        QueryName query = (QueryName) annotation;
470	        boolean encoded = query.encoded();
471	
472	        Class<?> rawParameterType = Utils.getRawType(type);
473	        gotQueryName = true;
474	        if (Iterable.class.isAssignableFrom(rawParameterType)) {
475	          if (!(type instanceof ParameterizedType)) {
476	            throw parameterError(
477	                method,
478	                p,
479	                rawParameterType.getSimpleName()
480	                    + " must include generic type (e.g., "
481	                    + rawParameterType.getSimpleName()
482	                    + "<String>)");
483	          }
484	          ParameterizedType parameterizedType = (ParameterizedType) type;
485	          Type iterableType = Utils.getParameterUpperBound(0, parameterizedType);
486	          Converter<?, String> converter = retrofit.stringConverter(iterableType, annotations);
487	          return new ParameterHandler.QueryName<>(converter, encoded).iterable();
488	        } else if (rawParameterType.isArray()) {
489	          Class<?> arrayComponentType = boxIfPrimitive(rawParameterType.getComponentType());
490	          Converter<?, String> converter =
491	              retrofit.stringConverter(arrayComponentType, annotations);
492	          return new ParameterHandler.QueryName<>(converter, encoded).array();
493	        } else {
494	          Converter<?, String> converter = retrofit.stringConverter(type, annotations);
495	          return new ParameterHandler.QueryName<>(converter, encoded);
496	        }
497	
498	      } else if (annotation instanceof QueryMap) {
499	        validateResolvableType(p, type);
500	        Class<?> rawParameterType = Utils.getRawType(type);
501	        gotQueryMap = true;
502	        if (!Map.class.isAssignableFrom(rawParameterType)) {
503	          throw parameterError(method, p, "@QueryMap parameter type must be Map.");
504	        }
505	        Type mapType = Utils.getSupertype(type, rawParameterType, Map.class);
506	        if (!(mapType instanceof ParameterizedType)) {
507	          throw parameterError(
508	              method, p, "Map must include generic types (e.g., Map<String, String>)");
509	        }
510	        ParameterizedType parameterizedType = (ParameterizedType) mapType;
511	        Type keyType = Utils.getParameterUpperBound(0, parameterizedType);
512	        if (String.class != keyType) {
513	          throw parameterError(method, p, "@QueryMap keys must be of type String: " + keyType);
514	        }
515	        Type valueType = Utils.getParameterUpperBound(1, parameterizedType);
516	        Converter<?, String> valueConverter = retrofit.stringConverter(valueType, annotations);
517	
518	        return new ParameterHandler.QueryMap<>(
519	            method, p, valueConverter, ((QueryMap) annotation).encoded());
520	
521	      } else if (annotation instanceof Header) {
522	        validateResolvableType(p, type);
523	        Header header = (Header) annotation;
524	        String name = header.value();
525	
526	        Class<?> rawParameterType = Utils.getRawType(type);
527	        if (Iterable.class.isAssignableFrom(rawParameterType)) {
528	          if (!(type instanceof ParameterizedType)) {
529	            throw parameterError(
530	                method,
531	                p,
532	                rawParameterType.getSimpleName()
533	                    + " must include generic type (e.g., "
534	                    + rawParameterType.getSimpleName()
535	                    + "<String>)");
536	          }
537	          ParameterizedType parameterizedType = (ParameterizedType) type;
538	          Type iterableType = Utils.getParameterUpperBound(0, parameterizedType);
539	          Converter<?, String> converter = retrofit.stringConverter(iterableType, annotations);
540	          return new ParameterHandler.Header<>(name, converter, header.allowUnsafeNonAsciiValues())
541	              .iterable();
542	        } else if (rawParameterType.isArray()) {
543	          Class<?> arrayComponentType = boxIfPrimitive(rawParameterType.getComponentType());
544	          Converter<?, String> converter =
545	              retrofit.stringConverter(arrayComponentType, annotations);
546	          return new ParameterHandler.Header<>(name, converter, header.allowUnsafeNonAsciiValues())
547	              .array();
548	        } else {
549	          Converter<?, String> converter = retrofit.stringConverter(type, annotations);
550	          return new ParameterHandler.Header<>(name, converter, header.allowUnsafeNonAsciiValues());
551	        }
552	
553	      } else if (annotation instanceof HeaderMap) {
554	        if (type == Headers.class) {
555	          return new ParameterHandler.Headers(method, p);
556	        }
557	
558	        validateResolvableType(p, type);
559	        Class<?> rawParameterType = Utils.getRawType(type);
560	        if (!Map.class.isAssignableFrom(rawParameterType)) {
561	          throw parameterError(method, p, "@HeaderMap parameter type must be Map or Headers.");
562	        }
563	        Type mapType = Utils.getSupertype(type, rawParameterType, Map.class);
564	        if (!(mapType instanceof ParameterizedType)) {
565	          throw parameterError(
566	              method, p, "Map must include generic types (e.g., Map<String, String>)");
567	        }
568	        ParameterizedType parameterizedType = (ParameterizedType) mapType;
569	        Type keyType = Utils.getParameterUpperBound(0, parameterizedType);
570	        if (String.class != keyType) {
571	          throw parameterError(method, p, "@HeaderMap keys must be of type String: " + keyType);
572	        }
573	        Type valueType = Utils.getParameterUpperBound(1, parameterizedType);
574	        Converter<?, String> valueConverter = retrofit.stringConverter(valueType, annotations);
575	
576	        return new ParameterHandler.HeaderMap<>(
577	            method, p, valueConverter, ((HeaderMap) annotation).allowUnsafeNonAsciiValues());
578	
579	      } else if (annotation instanceof Field) {
580	        validateResolvableType(p, type);
581	        if (!isFormEncoded) {
582	          throw parameterError(method, p, "@Field parameters can only be used with form encoding.");
583	        }
584	        Field field = (Field) annotation;
585	        String name = field.value();
586	        boolean encoded = field.encoded();
587	
588	        gotField = true;
589	
590	        Class<?> rawParameterType = Utils.getRawType(type);
591	        if (Iterable.class.isAssignableFrom(rawParameterType)) {
592	          if (!(type instanceof ParameterizedType)) {
593	            throw parameterError(
594	                method,
595	                p,
596	                rawParameterType.getSimpleName()
597	                    + " must include generic type (e.g., "
598	                    + rawParameterType.getSimpleName()
599	                    + "<String>)");
600	          }
601	          ParameterizedType parameterizedType = (ParameterizedType) type;
602	          Type iterableType = Utils.getParameterUpperBound(0, parameterizedType);
603	          Converter<?, String> converter = retrofit.stringConverter(iterableType, annotations);
604	          return new ParameterHandler.Field<>(name, converter, encoded).iterable();
605	        } else if (rawParameterType.isArray()) {
606	          Class<?> arrayComponentType = boxIfPrimitive(rawParameterType.getComponentType());
607	          Converter<?, String> converter =
608	              retrofit.stringConverter(arrayComponentType, annotations);
609	          return new ParameterHandler.Field<>(name, converter, encoded).array();
610	        } else {
611	          Converter<?, String> converter = retrofit.stringConverter(type, annotations);
612	          return new ParameterHandler.Field<>(name, converter, encoded);
613	        }
614	
615	      } else if (annotation instanceof FieldMap) {
616	        validateResolvableType(p, type);
617	        if (!isFormEncoded) {
618	          throw parameterError(
619	              method, p, "@FieldMap parameters can only be used with form encoding.");
620	        }
621	        Class<?> rawParameterType = Utils.getRawType(type);
622	        if (!Map.class.isAssignableFrom(rawParameterType)) {
623	          throw parameterError(method, p, "@FieldMap parameter type must be Map.");
624	        }
625	        Type mapType = Utils.getSupertype(type, rawParameterType, Map.class);
626	        if (!(mapType instanceof ParameterizedType)) {
627	          throw parameterError(
628	              method, p, "Map must include generic types (e.g., Map<String, String>)");
629	        }
630	        ParameterizedType parameterizedType = (ParameterizedType) mapType;
631	        Type keyType = Utils.getParameterUpperBound(0, parameterizedType);
632	        if (String.class != keyType) {
633	          throw parameterError(method, p, "@FieldMap keys must be of type String: " + keyType);
634	        }
635	        Type valueType = Utils.getParameterUpperBound(1, parameterizedType);
636	        Converter<?, String> valueConverter = retrofit.stringConverter(valueType, annotations);
637	
638	        gotField = true;
639	        return new ParameterHandler.FieldMap<>(
640	            method, p, valueConverter, ((FieldMap) annotation).encoded());
641	
642	      } else if (annotation instanceof Part) {
643	        validateResolvableType(p, type);
644	        if (!isMultipart) {
645	          throw parameterError(
646	              method, p, "@Part parameters can only be used with multipart encoding.");
647	        }
648	        Part part = (Part) annotation;
649	        gotPart = true;
650	
651	        String partName = part.value();
652	        Class<?> rawParameterType = Utils.getRawType(type);
653	        if (partName.isEmpty()) {
654	          if (Iterable.class.isAssignableFrom(rawParameterType)) {
655	            if (!(type instanceof ParameterizedType)) {
656	              throw parameterError(
657	                  method,
658	                  p,
659	                  rawParameterType.getSimpleName()
660	                      + " must include generic type (e.g., "
661	                      + rawParameterType.getSimpleName()
662	                      + "<String>)");
663	            }
664	            ParameterizedType parameterizedType = (ParameterizedType) type;
665	            Type iterableType = Utils.getParameterUpperBound(0, parameterizedType);
666	            if (!MultipartBody.Part.class.isAssignableFrom(Utils.getRawType(iterableType))) {
