672	            return ParameterHandler.RawPart.INSTANCE.iterable();
673	          } else if (rawParameterType.isArray()) {
674	            Class<?> arrayComponentType = rawParameterType.getComponentType();
675	            if (!MultipartBody.Part.class.isAssignableFrom(arrayComponentType)) {
676	              throw parameterError(
677	                  method,
678	                  p,
679	                  "@Part annotation must supply a name or use MultipartBody.Part parameter type.");
680	            }
681	            return ParameterHandler.RawPart.INSTANCE.array();
682	          } else if (MultipartBody.Part.class.isAssignableFrom(rawParameterType)) {
683	            return ParameterHandler.RawPart.INSTANCE;
684	          } else {
685	            throw parameterError(
686	                method,
687	                p,
688	                "@Part annotation must supply a name or use MultipartBody.Part parameter type.");
689	          }
690	        } else {
691	          Headers headers =
692	              Headers.of(
693	                  "Content-Disposition",
694	                  "form-data; name=\"" + partName + "\"",
695	                  "Content-Transfer-Encoding",
696	                  part.encoding());
697	
698	          if (Iterable.class.isAssignableFrom(rawParameterType)) {
699	            if (!(type instanceof ParameterizedType)) {
700	              throw parameterError(
701	                  method,
702	                  p,
703	                  rawParameterType.getSimpleName()
704	                      + " must include generic type (e.g., "
705	                      + rawParameterType.getSimpleName()
706	                      + "<String>)");
707	            }
708	            ParameterizedType parameterizedType = (ParameterizedType) type;
709	            Type iterableType = Utils.getParameterUpperBound(0, parameterizedType);
710	            if (MultipartBody.Part.class.isAssignableFrom(Utils.getRawType(iterableType))) {
711	              throw parameterError(
712	                  method,
713	                  p,
714	                  "@Part parameters using the MultipartBody.Part must not "
715	                      + "include a part name in the annotation.");
716	            }
717	            Converter<?, RequestBody> converter =
718	                retrofit.requestBodyConverter(iterableType, annotations, methodAnnotations);
719	            return new ParameterHandler.Part<>(method, p, headers, converter).iterable();
720	          } else if (rawParameterType.isArray()) {
721	            Class<?> arrayComponentType = boxIfPrimitive(rawParameterType.getComponentType());
722	            if (MultipartBody.Part.class.isAssignableFrom(arrayComponentType)) {
723	              throw parameterError(
724	                  method,
725	                  p,
726	                  "@Part parameters using the MultipartBody.Part must not "
727	                      + "include a part name in the annotation.");
728	            }
729	            Converter<?, RequestBody> converter =
730	                retrofit.requestBodyConverter(arrayComponentType, annotations, methodAnnotations);
731	            return new ParameterHandler.Part<>(method, p, headers, converter).array();
732	          } else if (MultipartBody.Part.class.isAssignableFrom(rawParameterType)) {
733	            throw parameterError(
734	                method,
735	                p,
736	                "@Part parameters using the MultipartBody.Part must not "
737	                    + "include a part name in the annotation.");
738	          } else {
739	            Converter<?, RequestBody> converter =
740	                retrofit.requestBodyConverter(type, annotations, methodAnnotations);
741	            return new ParameterHandler.Part<>(method, p, headers, converter);
742	          }
743	        }
744	
745	      } else if (annotation instanceof PartMap) {
746	        validateResolvableType(p, type);
747	        if (!isMultipart) {
748	          throw parameterError(
749	              method, p, "@PartMap parameters can only be used with multipart encoding.");
750	        }
751	        gotPart = true;
752	        Class<?> rawParameterType = Utils.getRawType(type);
753	        if (!Map.class.isAssignableFrom(rawParameterType)) {
754	          throw parameterError(method, p, "@PartMap parameter type must be Map.");
755	        }
756	        Type mapType = Utils.getSupertype(type, rawParameterType, Map.class);
757	        if (!(mapType instanceof ParameterizedType)) {
758	          throw parameterError(
759	              method, p, "Map must include generic types (e.g., Map<String, String>)");
760	        }
761	        ParameterizedType parameterizedType = (ParameterizedType) mapType;
762	
763	        Type keyType = Utils.getParameterUpperBound(0, parameterizedType);
764	        if (String.class != keyType) {
765	          throw parameterError(method, p, "@PartMap keys must be of type String: " + keyType);
766	        }
767	
768	        Type valueType = Utils.getParameterUpperBound(1, parameterizedType);
769	        if (MultipartBody.Part.class.isAssignableFrom(Utils.getRawType(valueType))) {
770	          throw parameterError(
771	              method,
772	              p,
773	              "@PartMap values cannot be MultipartBody.Part. "
774	                  + "Use @Part List<Part> or a different value type instead.");
775	        }
776	
777	        Converter<?, RequestBody> valueConverter =
778	            retrofit.requestBodyConverter(valueType, annotations, methodAnnotations);
779	
780	        PartMap partMap = (PartMap) annotation;
781	        return new ParameterHandler.PartMap<>(method, p, valueConverter, partMap.encoding());
782	
783	      } else if (annotation instanceof Body) {
784	        validateResolvableType(p, type);
785	        if (isFormEncoded || isMultipart) {
786	          throw parameterError(
787	              method, p, "@Body parameters cannot be used with form or multi-part encoding.");
788	        }
789	        if (gotBody) {
790	          throw parameterError(method, p, "Multiple @Body method annotations found.");
791	        }
792	
793	        Converter<?, RequestBody> converter;
794	        try {
795	          converter = retrofit.requestBodyConverter(type, annotations, methodAnnotations);
796	        } catch (RuntimeException e) {
797	          // Wide exception range because factories are user code.
798	          throw parameterError(method, e, p, "Unable to create @Body converter for %s", type);
799	        }
800	        gotBody = true;
801	        return new ParameterHandler.Body<>(method, p, converter);
802	
803	      } else if (annotation instanceof Tag) {
804	        validateResolvableType(p, type);
805	
806	        Class<?> tagType = boxIfPrimitive(Utils.getRawType(type));
807	        for (int i = p - 1; i >= 0; i--) {
808	          ParameterHandler<?> otherHandler = parameterHandlers[i];
809	          if (otherHandler instanceof ParameterHandler.Tag
810	              && ((ParameterHandler.Tag) otherHandler).cls.equals(tagType)) {
811	            throw parameterError(
812	                method,
813	                p,
814	                "@Tag type "
815	                    + tagType.getName()
816	                    + " is duplicate of "
817	                    + Platform.reflection.describeMethodParameter(method, i)
818	                    + " and would always overwrite its value.");
819	          }
820	        }
821	
822	        return new ParameterHandler.Tag<>(tagType);
823	      }
824	
825	      return null; // Not a Retrofit annotation.
826	    }
827	
828	    private void validateResolvableType(int p, Type type) {
829	      if (Utils.hasUnresolvableType(type)) {
830	        throw parameterError(
831	            method, p, "Parameter type must not include a type variable or wildcard: %s", type);
832	      }
833	    }
834	
835	    private void validatePathName(int p, String name) {
836	      if (!PARAM_NAME_REGEX.matcher(name).matches()) {
837	        throw parameterError(
838	            method,
839	            p,
840	            "@Path parameter name must match %s. Found: %s",
841	            PARAM_URL_REGEX.pattern(),
842	            name);
843	      }
844	      // Verify URL replacement name is actually present in the URL path.
845	      if (!relativeUrlParamNames.contains(name)) {
846	        throw parameterError(method, p, "URL \"%s\" does not contain \"{%s}\".", relativeUrl, name);
847	      }
848	    }
849	
850	    /**
851	     * Gets the set of unique path parameters used in the given URI. If a parameter is used twice in
852	     * the URI, it will only show up once in the set.
853	     */
854	    static Set<String> parsePathParameters(String path) {
855	      Matcher m = PARAM_URL_REGEX.matcher(path);
856	      Set<String> patterns = new LinkedHashSet<>();
857	      while (m.find()) {
858	        patterns.add(m.group(1));
859	      }
860	      return patterns;
861	    }
862	
863	    private static Class<?> boxIfPrimitive(Class<?> type) {
864	      if (boolean.class == type) return Boolean.class;
865	      if (byte.class == type) return Byte.class;
866	      if (char.class == type) return Character.class;
867	      if (double.class == type) return Double.class;
868	      if (float.class == type) return Float.class;
869	      if (int.class == type) return Integer.class;
870	      if (long.class == type) return Long.class;
871	      if (short.class == type) return Short.class;
872	      return type;
873	    }
874	  }
875	}
